(function(){'use strict';const P=G0Risks,$=id=>document.getElementById(id),write=(id,v)=>$(id).textContent=JSON.stringify(v,null,2);let claim;
function run(){const f=P.pixelFixture(),ctx=$('pixels').getContext('2d');ctx.putImageData(new ImageData(f.pixels,f.width,f.height),0,0);const visible=ctx.getImageData(0,0,f.width,f.height);write('m1',{components:P.components(visible.data,f.width,f.height).map(a=>({pixelArea:a.length})),denominator:'384 visible pixels; two sparse opaque regions; no lithology model'});
const rows=Array.from({length:13},(_,i)=>({time_s:i*10,flow:i>=3&&i<6?0:1,depthMD_m:1200+i}));write('m2',{volume_m3:60,source_s:0,arrival_s:M2Core.arrivalAt(rows,0,60),cumulativeVolume_m3:M2Core.cumulative(rows),backQuery_s:M2Core.sourceAt(rows,90,60)});write('m4',P.m4());extract();claim={claimId:'prototype',revision:1,statement:'教学记录未见荧光',reviewStatus:'confirmed',traceabilityStatus:'linked',supportStatus:'human_verified',reviewHistory:[]};write('claim',claim);}
function extract(){write('m5',P.extract($('text').value));}$('run').onclick=run;$('extract').onclick=extract;$('invalidate').onclick=()=>{claim=P.invalidate(claim,'source version changed');write('claim',claim);};run();})();
